const normalizePhone=(value:string)=>value.replace(/[^\d]/g,'');
const nativeUnreadCount=(item:InboxItem)=>Math.max(0,Math.floor(Number(item.unreadCount)||0));
// Older saved records did not carry lastValidDirection. Retain their existing
