const conversationLastValidDirection=(item:InboxItem):LastValidDirection=>Object.prototype.hasOwnProperty.call(item,'lastValidDirection')?item.lastValidDirection??null:item.direction==='customer'?'customer':item.direction==='merchant'?'merchant':null;
