const mediaFailurePolicy:Record<string,Omit<ChatMediaFailure,'code'>>={
 WHATSAPP_MEDIA_LOOKUP_UNAVAILABLE:{message:'暂时无法从 WhatsApp 读取这张历史图片。请在 WhatsApp 打开当前聊天后，再点击重试。',retryable:true},
 WHATSAPP_MEDIA_NOT_FOUND:{message:'WhatsApp 当前未返回这张历史图片。请在 WhatsApp 打开当前聊天后，再点击重试。',retryable:true},
 WHATSAPP_MEDIA_UNAVAILABLE:{message:'WhatsApp 暂未返回这张图片数据。请在 WhatsApp 打开当前聊天后，再点击重试。',retryable:true},
 WHATSAPP_TIMEOUT:{message:'图片读取超时，请稍后重试。',retryable:true},
 WHATSAPP_MEDIA_BUSY:{message:'图片读取请求较多，请稍后重试。',retryable:true},
 WHATSAPP_MEDIA_CANCELLED:{message:'WhatsApp 连接已变化，请重新打开当前聊天后重试。',retryable:true},
 WHATSAPP_CONNECTION:{message:'WhatsApp 连接暂时不可用，请恢复连接后重试。',retryable:true},
 WHATSAPP_MEDIA_INVALID:{message:'WhatsApp 返回的图片内容无法安全显示，请稍后重试。',retryable:true},
 WHATSAPP_MEDIA_TOO_LARGE:{message:'图片超过本机 16 MB 读取保护，请在 WhatsApp 查看原图。',retryable:false},
 WHATSAPP_MEDIA_UNSUPPORTED:{message:'当前图片格式暂不支持本机显示，请在 WhatsApp 查看原文件。',retryable:false},
 WHATSAPP_MEDIA_IDENTITY:{message:'为保护当前会话安全，未读取这张图片。请重新打开并核对当前聊天。',retryable:false}
};
const safeMediaFailure=(value:unknown):ChatMediaFailure=>{
 const raw=value&&typeof value==='object'?value as ApiError:{},requested=String(raw.code||'').replace(/[^A-Z0-9_]/g,'').slice(0,80),policy=mediaFailurePolicy[requested];
 return policy?{code:requested,...policy}:{code:'WHATSAPP_MEDIA_READ_FAILED',message:'图片暂时无法读取，可稍后重试。',retryable:true};
};
const safeLink=(value:string)=>{try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:null;}catch{return null;}};
const messageLinks=(value:string)=>[...new Set(value.match(/https?:\/\/[^\s<>"']+/g)||[])].map(safeLink).filter((value):value is string=>Boolean(value));
const mapAddressFromLink=(href:string)=>{try{const url=new URL(href),host=url.hostname.toLowerCase(),google=host==='google.com'||host.endsWith('.google.com');if(!google||!url.pathname.startsWith('/maps'))return null;const candidate=url.searchParams.get('q')||url.searchParams.get('query')||url.searchParams.get('destination')||decodeURIComponent(url.pathname.match(/^\/maps\/search\/([^/]+)/)?.[1]||'');const value=candidate.replace(/\+/g,' ').trim();if(!value||value.length>500||/^-?\d{1,2}(?:\.\d+)?\s*,\s*-?\d{1,3}(?:\.\d+)?$/.test(value))return null;return value;}catch{return null;}};
const isSystemMessage=(m:ChatMessage)=>['notification_template','e2e_notification','revoked'].includes(String(m.metadata?.messageType||''));
const isMediaOnlyMessage=(m:ChatMessage)=>Boolean(m.metadata?.media?.length)&&/^\[(?:图片|贴纸|GIF 动图|媒体附件|视频)\]$/.test(m.text.trim());
const systemMessageText=(m:ChatMessage)=>m.metadata?.messageType==='revoked'?'此消息已撤回。':m.metadata?.messageType==='e2e_notification'?'WhatsApp 加密通知。':!m.text.trim()||/^\[(?:未知类型消息|非文字消息[^\]]*)\]$/.test(m.text.trim())?'WhatsApp 系统通知。':m.text;
const safeMediaUrl=(value:unknown)=>typeof value==='string'&&/^data:image\/(?:png|jpeg|webp|gif);base64,[A-Za-z0-9+/]+=*$/.test(value)?value:null;
const safeVideoUrl=(value:unknown)=>typeof value==='string'&&/^data:video\/mp4;base64,[A-Za-z0-9+/]+=*$/.test(value)?value:null;
const messageKey=(value:string)=>value.replace(/^(true|false)_[^_]+_/,'$1_');
const deliveryAck=(message:ChatMessage)=>{const value=Number(message.metadata?.deliveryAck);return message.direction==='merchant'&&Number.isInteger(value)&&value>=-1&&value<=4?value:null;};
const mergeMessages=(current:ChatMessage[],incoming:ChatMessage[])=>{
 const rows=new Map<string,ChatMessage>();
 for(const row of current)rows.set(messageKey(row.id),row);
 for(const row of incoming){const key=messageKey(row.id),previous=rows.get(key),hasCachedImage=previous?.metadata?.media?.some(media=>media.status==='cached'&&Boolean(safeMediaUrl(media.dataUrl))),incomingAck=deliveryAck(row),previousAck=previous?deliveryAck(previous):null,metadata={...row.metadata,...(hasCachedImage?{media:previous?.metadata?.media}:{}),...(incomingAck===null&&previousAck!==null?{deliveryAck:previousAck}:{})};rows.set(key,hasCachedImage||incomingAck===null&&previousAck!==null?{...row,metadata}:row);}
 return [...rows.values()].sort((a,b)=>a.sentAt.localeCompare(b.sentAt)||a.id.localeCompare(b.id));
};

type WorkbenchRequest={request:(value:unknown)=>Promise<{ok:boolean;data?:unknown;error?:ApiError|string}>};
type TranslationWorkbenchRequest={request:(value:unknown)=>Promise<{ok:boolean;data?:unknown;error?:string}>};
type AdsPowerInboxRequest={scan:()=>Promise<ApiResult<AdsPowerScanResult>>;translate:(payload:{token:string;messageIds:string[]})=>Promise<ApiResult<{translations:{id:string;text:string}[]}>>;clear:(payload:{token:string})=>Promise<ApiResult<{cleared:boolean}>>};
type WorkbenchBridgeWindow=Window&{manualChat?:WorkbenchRequest;manualReplyTranslation?:TranslationWorkbenchRequest;adsPowerInbox?:AdsPowerInboxRequest};
// The workbench is a controlled srcdoc child of the local dashboard. In the
// packaged app it deliberately has no raw Electron bridge; it may use only the
// same-origin parent's token-bound request facades.
const workbenchHost=():WorkbenchBridgeWindow=>{try{return window.parent!==window&&window.parent.location.origin===window.location.origin?window.parent as WorkbenchBridgeWindow:window as WorkbenchBridgeWindow;}catch{return window as WorkbenchBridgeWindow;}};
function ordersApi<T>(name:string,payload?:unknown){const fn=window.inventoryApp?.orders?.[name]||workbenchHost().inventoryApp?.orders?.[name];if(!fn)return Promise.reject(new Error('订单服务尚未就绪'));return fn(payload).then((result:ApiResult<T>)=>{if(!result.ok)throw new Error(typeof result.error==='string'?result.error:result.error?.message||'订单操作失败');return result.data as T;});}
function chatApi<T>(action:string,payload?:unknown){const api=(window as WorkbenchBridgeWindow).manualChat||workbenchHost().manualChat;if(!api)return Promise.reject(new Error('请在连接与设置完成 WhatsApp 登录'));return api.request({action,payload}).then(result=>{if(!result.ok){const detail=typeof result.error==='string'?{message:result.error}:result.error||{},failure=Object.assign(new Error(detail.message||'聊天操作失败'),{code:detail.code,retryable:detail.retryable});throw failure;}return result.data as T;});}
function translationApi<T>(action:string,payload?:unknown){const api=(window as WorkbenchBridgeWindow).manualReplyTranslation||workbenchHost().manualReplyTranslation;if(!api)return Promise.reject(new Error('翻译服务未就绪'));return api.request({action,payload}).then(result=>{if(!result.ok)throw new Error(result.error||'翻译失败');return result.data as T;});}
function adsPowerApi<T>(action:'scan'|'translate'|'clear',payload?:{token:string;messageIds?:string[]}){const api=(window as WorkbenchBridgeWindow).adsPowerInbox||workbenchHost().adsPowerInbox;if(!api)return Promise.reject(new Error('AdsPower 扫描服务未就绪'));const request=action==='scan'?api.scan():action==='translate'?api.translate({token:payload?.token||'',messageIds:payload?.messageIds||[]}):api.clear({token:payload?.token||''});return request.then(result=>{if(!result.ok)throw new Error(typeof result.error==='string'?result.error:result.error?.message||'AdsPower 扫描操作失败');return result.data as T;});}

