 async function loadReportPreview(orderId:string){try{const value=await ordersApi<{content?:string|null;problems?:{label?:string}[];token?:string}>('previewPackageTxt',{orderId});if(closed||detail?.id!==orderId)return;reportPreview={orderId,loading:false,content:value.content||null,problems:value.problems||[],token:value.token};renderOrder();}catch(error){if(closed||detail?.id!==orderId)return;reportPreview={orderId,loading:false,content:null,problems:[{label:`报单读取失败：${(error as Error).message}`} ]};renderOrder();}}
